#include <stdio.h>

typedef int *IntArray;

// Медиана — средний элемент в отсортированном порядке (при чётном n — левый из двух средних).
// Функция не должна менять переданный массив.
int median(const IntArray values, int n) {
    for (int i = 1; i < n; i++) {                 // сортировка вставками
        int key = values[i];
        int j = i - 1;
        while (j >= 0 && values[j] > key) {
            values[j + 1] = values[j];
            j--;
        }
        values[j + 1] = key;
    }
    return values[(n - 1) / 2];
}

int main(void) {
    int n, data[100];
    if (scanf("%d", &n) != 1 || n < 1 || n > 100) {
        return 0;
    }
    for (int i = 0; i < n; i++) {
        if (scanf("%d", &data[i]) != 1) {
            return 0;
        }
    }
    printf("медиана: %d\n", median(data, n));
    printf("исходный порядок:");
    for (int i = 0; i < n; i++) {
        printf(" %d", data[i]);
    }
    printf("\n");
    return 0;
}

