#include <ctype.h>
#include <stdio.h>
#include <string.h>

static const int VALUES[13] = {1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1};
static const char *const SYMBOLS[13] = {"M", "CM", "D", "CD", "C", "XC", "L",
                                        "XL", "X", "IX", "V", "IV", "I"};

static void to_roman(int value, char *out) {
    out[0] = '\0';
    for (int i = 0; i < 13; i++) {
        while (value >= VALUES[i]) {
            strcat(out, SYMBOLS[i]);
            value -= VALUES[i];
        }
    }
}

// Возвращает значение или -1, если в строке встретилось неизвестное обозначение.
static int from_roman(const char *text) {
    int value = 0;
    while (*text != '\0') {
        int found = 0;
        for (int i = 0; i < 13 && !found; i++) {
            size_t len = strlen(SYMBOLS[i]);
            if (strncmp(text, SYMBOLS[i], len) == 0) {
                value += VALUES[i];
                text += len;
                found = 1;
            }
        }
        if (!found) {
            return -1;
        }
    }
    return value;
}

int main(void) {
    char word[32];
    while (scanf("%31s", word) == 1) {
        char roman[32];
        if (isdigit((unsigned char)word[0])) {
            int value;
            if (sscanf(word, "%d", &value) != 1 || value < 1 || value > 3999 ||
                strspn(word, "0123456789") != strlen(word)) {
                printf("ошибка\n");
                continue;
            }
            to_roman(value, roman);
            printf("%s\n", roman);
        } else {
            int value = from_roman(word);
            if (value < 1 || value > 3999) {
                printf("ошибка\n");
                continue;
            }
            to_roman(value, roman);
            if (strcmp(roman, word) != 0) {
                printf("ошибка\n");
            } else {
                printf("%d\n", value);
            }
        }
    }
    return 0;
}

