#include <ctype.h>
#include <stdio.h>

enum State {
    START, SIGN, INT, DOT_FIRST, INT_DOT, FRAC, EXP, EXP_SIGN, EXP_DIGITS, ERROR, STATE_COUNT
};
enum CharClass { DIGIT, SIGN_CHAR, DOT, EXP_CHAR, OTHER, CLASS_COUNT };

static const unsigned char NEXT[STATE_COUNT][CLASS_COUNT] = {
    //             цифра       знак      точка      e        прочее
    [START]      = {INT,        SIGN,     DOT_FIRST, ERROR,   ERROR},
    [SIGN]       = {INT,        ERROR,    DOT_FIRST, ERROR,   ERROR},
    [INT]        = {INT,        ERROR,    INT_DOT,   EXP,     ERROR},
    [DOT_FIRST]  = {FRAC,       ERROR,    ERROR,     ERROR,   ERROR},
    [INT_DOT]    = {FRAC,       ERROR,    ERROR,     EXP,     ERROR},
    [FRAC]       = {FRAC,       ERROR,    ERROR,     EXP,     ERROR},
    [EXP]        = {EXP_DIGITS, EXP_SIGN, ERROR,     ERROR,   ERROR},
    [EXP_SIGN]   = {EXP_DIGITS, ERROR,    ERROR,     ERROR,   ERROR},
    [EXP_DIGITS] = {EXP_DIGITS, ERROR,    ERROR,     ERROR,   ERROR},
    [ERROR]      = {ERROR,      ERROR,    ERROR,     ERROR,   ERROR},
};

static enum CharClass char_class(char c) {
    if (isdigit((unsigned char)c)) {
        return DIGIT;
    }
    if (c == '+' || c == '-') {
        return SIGN_CHAR;
    }
    if (c == '.') {
        return DOT;
    }
    if (c == 'e' || c == 'E') {
        return EXP_CHAR;
    }
    return OTHER;
}

int main(void) {
    char word[64];
    while (scanf("%63s", word) == 1) {
        enum State state = START;
        for (const char *p = word; *p != '\0'; p++) {
            state = (enum State)NEXT[state][char_class(*p)];
        }
        const char *kind = "не число";
        if (state == INT) {
            kind = "целое";
        } else if (state == INT_DOT || state == FRAC || state == EXP_DIGITS) {
            kind = "вещественное";
        }
        printf("%s: %s\n", word, kind);
    }
    return 0;
}

