static const int PRICES[] = {50, 120, 80, 200};
enum { ITEM_COUNT = sizeof PRICES / sizeof PRICES[0] };

int main(void) {
    int basket[] = {1, 3, 3, 0};
    int total = 0;
    for (int i = 0; i < ITEM_COUNT; i++) {
        total += PRICES[basket[i]];
    }
    printf("%d %d\n", ITEM_COUNT, total);
    return 0;
}
